def analyze_attendance_records(attendance_records, threshold=5):
    result = {}
    student_records = {}

    for record in attendance_records:
        student_id = record['student_id']
        date = record['date']
        attendance_status = record['attendance_status']

        if student_id not in student_records:
            student_records[student_id] = []

        if attendance_status != 'present':
            student_records[student_id].append(date)

    for student_id, dates in student_records.items():
        if len(dates) >= threshold:
            result[student_id] = dates

    return result

