def calculate_gini(income_list):
    n = len(income_list)
    if n <= 1:
        return 0.0  # Perfect equality for empty or single-element list

    income_sum = sum(income_list)
    mean_income = income_sum / n

    numerator = 0
    for i in range(n):
        for j in range(n):
            numerator += abs(income_list[i] - income_list[j])

    gini_coefficient = numerator / (2 * n**2 * mean_income)
    return gini_coefficient

