def generate_order_summary(orders):
    rodents_summary = {}
    customizations_summary = {}

    for order in orders:
        # Update rodents summary
        for rodent in order["rodents"]:
            rodents_summary[rodent] = rodents_summary.get(rodent, 0) + 1

        # Update customizations summary
        for option, value in order["customizations"].items():
            if option not in customizations_summary:
                customizations_summary[option] = {}
            customizations_summary[option][value] = customizations_summary[option].get(value, 0) + 1

    return {
