def analyze_employment_changes(before_development, after_development):
    # Create a dictionary to store the total employment rates before and after development
    total_before = {}
    total_after = {}

    # Iterate through the lists and calculate the total employment rates
    for data in before_development:
        for sector, rate in data.items():
            total_before[sector] = total_before.get(sector, 0) + rate

    for data in after_development:
        for sector, rate in data.items():
            total_after[sector] = total_after.get(sector, 0) + rate

    # Calculate the absolute change in employment rates
    changes = {}
    for sector in set(total_before.keys()) | set(total_after.keys()):
        before_rate = total_before.get(sector, 0)
        after_rate = total_after.get(sector, 0)
        changes[sector] = abs(after_rate - before_rate)

    return changes

def parse_treaty_data(file_path):
