    with open(file_path, 'r') as file:
        for line in file:
            line = line.strip()

            if line.startswith('Treaty:'):
                if current_treaty:
                    treaties.append(current_treaty)
                    current_treaty = {}
                current_treaty['name'] = line.split(':', 1)[1].strip()
            elif line.startswith('Year:'):
                current_treaty['year'] = int(line.split(':', 1)[1].strip())
            elif line.startswith('Countries:'):
                current_treaty['countries'] = [country.strip() for country in line.split(':', 1)[1].split(',')]
            elif line.startswith('Measures:'):
                current_treaty['measures'] = line.split(':', 1)[1].strip()

        if current_treaty:
            treaties.append(current_treaty)

    return treaties

def merge_lists(list1, list2, key):
    result = []
    dict_from_list1 = {d[key]: d for d in list1}
    dict_from_list2 = {d[key]: d for d in list2}

    for k, v in dict_from_list1.items():
        merged_dict = v.copy()
        if k in dict_from_list2:
            merged_dict.update(dict_from_list2[k])
        result.append(merged_dict)

    for k, v in dict_from_list2.items():
        if k not in dict_from_list1:
            result.append(v)

    return result

