    losses = 0
    ties = 0

    for game in games:
        teams = game.split("-")
        team1, score1 = teams[0].split(":")
        team2, score2 = teams[1].split(":")

        if team1 == team_name:
            if int(score1) > int(score2):
                wins += 1
            elif int(score1) < int(score2):
                losses += 1
            else:
                ties += 1
        else:
            if int(score2) > int(score1):
                wins += 1
            elif int(score2) < int(score1):
                losses += 1
            else:
