    # Check for anaphora
    prev_sentence_start = None
    for sentence in sentences:
        sentence = sentence.strip()
        if sentence:
            current_sentence_start = sentence.split()[0]
            if prev_sentence_start and current_sentence_start == prev_sentence_start:
                anaphora_count += 1
            prev_sentence_start = current_sentence_start

    # Check for epistrophe
    prev_sentence_end = None
    for sentence in sentences:
        sentence = sentence.strip()
        if sentence:
            current_sentence_end = sentence.split()[-1]
            if prev_sentence_end and current_sentence_end == prev_sentence_end:
                epistrophe_count += 1
            prev_sentence_end = current_sentence_end

    # Check for antithesis (simple pattern: "not X but Y")
    for sentence in sentences:
        sentence = sentence.strip()
        if 'not' in sentence and 'but' in sentence:
            antithesis_count += 1

    return {
        'anaphora': anaphora_count,
        'epistrophe': epistrophe_count,
        'antithesis': antithesis_count
    }

