        if drug_name in result:
            current_data = result[drug_name]
            total_efficacy = current_data['average_efficacy'] * current_data['total_sample_size'] + efficacy_rate * sample_size
            total_sample_size = current_data['total_sample_size'] + sample_size
            average_efficacy = total_efficacy / total_sample_size
            result[drug_name] = {'average_efficacy': average_efficacy, 'total_sample_size': total_sample_size}
