def calculate_ema(prices, days):
    ema = []
    smoothing = 2
    sma = sum(prices[:days]) / days

    for i in range(len(prices)):
        if i < days:
            ema.append(sma)
        else:
            ema_today = (prices[i] * smoothing / (1 + days)) + (ema[-1] * (days / (1 + days)))
            ema.append(ema_today)

    return ema

