def longest_consecutive_sequence(nums):
    num_set = set(nums)
    max_seq = []

    for num in nums:
        if num - 1 not in num_set:
            curr_num = num
            curr_seq = []

            while curr_num in num_set:
                curr_seq.append(curr_num)
                curr_num += 1

            if len(curr_seq) > len(max_seq):
                max_seq = curr_seq

    return max_seq

