def find_available_concerts(free_time_slots, concert_schedules):
    available_concerts = []

    def convert_to_minutes(time_str):
        hour, minute = map(int, time_str.split(':'))
        return hour * 60 + minute

    for free_start, free_end in free_time_slots:
        free_start_minutes = convert_to_minutes(free_start)
        free_end_minutes = convert_to_minutes(free_end)

        for concert_start, concert_end in concert_schedules:
            concert_start_minutes = convert_to_minutes(concert_start)
            concert_end_minutes = convert_to_minutes(concert_end)

            if free_start_minutes <= concert_start_minutes and concert_end_minutes <= free_end_minutes:
                available_concerts.append((concert_start, concert_end))

    return available_concerts

