def longest_consecutive_unique_chars(s):
    longest = 1
    current = 1
    seen = set()

    for char in s:
        if char not in seen:
            seen.add(char)
            current += 1
        else:
            longest = max(longest, current)
            current = 1
            seen = set()
            seen.add(char)

    return max(longest, current)

def is_melody(s):
    i, o, n = -1, -1, -1
    for idx, char in enumerate(s.lower()):
        if char == 'i':
            i = idx
        elif char == 'o' and i != -1:
            o = idx
        elif char == 'n' and o != -1:
            n = idx
            break
    return i != -1 and o != -1 and n != -1 and i < o < n

